import React, { useState, useEffect } from 'react'
import { MapContainer, TileLayer, Marker, Popup, useMapEvents } from 'react-leaflet'
import { supabase } from './supabaseClient'
import 'leaflet/dist/leaflet.css'
import L from 'leaflet'

// Fix for default marker icons
delete L.Icon.Default.prototype._getIconUrl
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
})

function AddMarkerOnClick({ onAddSite }) {
  useMapEvents({
    click(e) {
      const { lat, lng } = e.latlng
      const siteName = prompt('Name this derelict site:')
      if (siteName) {
        onAddSite({ lat, lng, name: siteName })
      }
    },
  })
  return null
}

function Map() {
  const [sites, setSites] = useState([])
  const [userLocation, setUserLocation] = useState([51.9, -8.47]) // Cork default
  const [loading, setLoading] = useState(true)

  // Load sites from Supabase
  useEffect(() => {
    loadSites()
    
    // Get user's location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((position) => {
        setUserLocation([position.coords.latitude, position.coords.longitude])
      })
    }
  }, [])

  const loadSites = async () => {
    try {
      const { data, error } = await supabase
        .from('derelict_sites')
        .select('*')
        .order('created_at', { ascending: false })

      if (error) throw error
      setSites(data || [])
    } catch (error) {
      console.error('Error loading sites:', error)
      alert('Error loading sites. Check console for details.')
    } finally {
      setLoading(false)
    }
  }

  const handleAddSite = async (newSite) => {
    try {
      const { data, error } = await supabase
        .from('derelict_sites')
        .insert([
          {
            name: newSite.name,
            latitude: newSite.lat,
            longitude: newSite.lng,
          }
        ])
        .select()

      if (error) throw error
      
      // Add to local state
      setSites([...sites, data[0]])
      alert(`✅ Added: ${newSite.name}`)
    } catch (error) {
      console.error('Error adding site:', error)
      alert('Error saving site. Check console for details.')
    }
  }

  if (loading) {
    return <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
      Loading map...
    </div>
  }

  return (
    <div style={{ height: '100vh', width: '100%' }}>
      <div style={{
        position: 'absolute',
        top: '10px',
        left: '50%',
        transform: 'translateX(-50%)',
        zIndex: 1000,
        background: 'white',
        padding: '10px 20px',
        borderRadius: '8px',
        boxShadow: '0 2px 10px rgba(0,0,0,0.2)',
        fontFamily: 'Arial, sans-serif'
      }}>
        🏚️ <strong>{sites.length}</strong> derelict sites found | Click map to add new site
      </div>

      <MapContainer
        center={userLocation}
        zoom={13}
        style={{ height: '100%', width: '100%' }}
      >
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
        />
        
        <AddMarkerOnClick onAddSite={handleAddSite} />
        
        {sites.map((site) => (
          <Marker key={site.id} position={[site.latitude, site.longitude]}>
            <Popup>
              <strong>{site.name}</strong>
              <br />
              <small>{new Date(site.created_at).toLocaleDateString()}</small>
            </Popup>
          </Marker>
        ))}
      </MapContainer>
    </div>
  )
}

export default Map
